/**
 * The overview screen (`design/archetypes/dashboard.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dashboard.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  SlotOutlet,
  SlotTemplate,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/dashboard.module.css'
import { Card } from '../structure/Card'
import { PageHeader, type PageHeaderProps } from '../structure/PageHeader'
import { Stat, type StatProps } from '../structure/Stat'

/** The overview screen: the inputs it takes, by the React member's prop names. */
export interface DashboardProps {
  description?: string
  /**
   * Two to four stats, because more than four belong in a table.
   */
  stats?: StatProps[]
  title: string
}

/** The overview screen. */
@Component({
  selector: 'pm-dashboard',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, Card, PageHeader, Stat],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="primary" [pmSlotOf]="$"><ng-content select="[slot=primary]" /></ng-template>
<ng-template pmSlot="secondary" [pmSlotOf]="$"><ng-content select="[slot=secondary]" /></ng-template>
<ng-template pmSlot="titleEdit" [pmSlotOf]="$"><ng-content select="[slot=titleEdit]" /></ng-template>
<!-- page -->
<div
[attr.class]="e1()"
data-member="dashboard"
><pm-page-header
[title]="e2()"
[description]="e3()"
>@if (e4()) {<ng-container ngProjectAs="[slot=titleEdit]"><ng-container [pmSlotOutlet]="'titleEdit'" [pmSlotOf]="$" pmSlotInto="titleEdit" /></ng-container>}
@if (e5()) {<ng-container ngProjectAs="[slot=actions]"><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="actions" /></ng-container>}</pm-page-header>
@if (e6()) {<!-- stats -->
<div
[attr.class]="e7()"
[attr.data-count]="e8()"
>@for (stat of e9(); track e10(stat, $index); let at = $index) {<pm-card><pm-stat
[label]="e11(stat)"
[value]="e12(stat)"
[numeric]="e13(stat)"
[icon]="e14(stat)"
[delta]="e15(stat)"
[trend]="e16(stat)"
[spark]="e17(stat)"
[sparkLabel]="e18(stat)"
[description]="e19(stat)"
[footer]="e20(stat)"
></pm-stat></pm-card>}</div>}
<!-- body -->
<div
[attr.class]="e21()"
[attr.data-secondary]="e22()"
><!-- primary -->
<div
[attr.class]="e23()"
><ng-container [pmSlotOutlet]="'primary'" [pmSlotOf]="$" /></div>
@if (e24()) {<!-- secondary -->
<div
[attr.class]="e25()"
><ng-container [pmSlotOutlet]="'secondary'" [pmSlotOf]="$" /></div>}</div></div>`,
})
export class Dashboard {
  readonly description = input<DashboardProps['description']>(undefined)
  /**
   * Two to four stats, because more than four belong in a table.
   */
  readonly stats = input<DashboardProps['stats']>(undefined)
  readonly title = input.required<DashboardProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      description: () => this.description(),
      stats: () => this.stats(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props

  constructor() {
    this.$.pass('titleEdit', () => ({ valueHidden: true }))
  }

  protected e1() {
    return styles.page
  }

  protected e2(): PageHeaderProps['title'] {
    return this.$p.title
  }

  protected e3(): PageHeaderProps['description'] {
    return this.$p.description
  }

  protected e4() {
    return this.$.filled('titleEdit')
  }

  protected e5() {
    return this.$.filled('actions')
  }

  protected e6() {
    return this.$p.stats !== undefined && this.$p.stats.length > 0
  }

  protected e7() {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return styles.stats
  }

  protected e8() {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return String(this.$p.stats.length)
  }

  e9() {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return this.$p.stats
  }

  protected e10(stat: Each<ReturnType<Dashboard['e9']>>, at: number) {
    return `${at}-${stat.label}`
  }

  protected e11(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['label'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.label
  }

  protected e12(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['value'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.value
  }

  protected e13(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['numeric'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.numeric
  }

  protected e14(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['icon'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.icon
  }

  protected e15(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['delta'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.delta
  }

  protected e16(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['trend'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.trend
  }

  protected e17(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['spark'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.spark
  }

  protected e18(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['sparkLabel'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.sparkLabel
  }

  protected e19(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['description'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.description
  }

  protected e20(stat: Each<ReturnType<Dashboard['e9']>>): StatProps['footer'] {
    if (!(this.$p.stats !== undefined && this.$p.stats.length > 0)) return undefined as never
    return stat.footer
  }

  protected e21() {
    return styles.body
  }

  protected e22() {
    return this.$.filled('secondary') ? '' : undefined
  }

  protected e23() {
    return styles.primary
  }

  protected e24() {
    return this.$.filled('secondary')
  }

  protected e25() {
    if (!this.$.filled('secondary')) return undefined as never
    return styles.secondary
  }
}
